package order

import (
  "context"
  "errors"

  "gorm.io/gorm"
)

var ErrOutOfStock = errors.New("out of stock")

type Order struct {
  ID     uint
  UserID uint
  ItemID uint
}

type Stock struct {
  ItemID   uint `gorm:"primaryKey"`
  Quantity int
}

func Place(ctx context.Context, db *gorm.DB, userID, itemID uint) error {
  return db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
    if err := db.Create(&Order{UserID: userID, ItemID: itemID}).Error; err != nil {
      return err
    }
    res := db.Model(&Stock{}).
      Where("item_id = ? AND quantity > 0", itemID).
      Update("quantity", gorm.Expr("quantity - 1"))
    if res.Error != nil {
      return res.Error
    }
    if res.RowsAffected == 0 {
      return ErrOutOfStock
    }
    return nil
  })
}

