  UserID   uint
  ItemID   uint
  Quantity int
}

func Place(ctx context.Context, db *gorm.DB, userID, itemID uint, qty int) error {
  return db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
    order := Order{UserID: userID, ItemID: itemID, Quantity: qty}
    if err := tx.Create(&order).Error; err != nil {
      return err
    }
    if err := tx.Model(&Stock{}).
      Where("item_id = ? AND quantity >= ?", itemID, qty).
      Update("quantity", gorm.Expr("quantity - ?", qty)).Error; err != nil {
      return err
    }
    if tx.RowsAffected == 0 {
      return ErrOutOfStock
    }
    return nil
  })
}

